89:         date.setTime(date.getTime()+(days*24*60*60*1000));
90:         expires = "; expires="+date.toGMTString();
91:     }
92:     else {
93:         expires = "";
94:     }
95:     document.cookie = name+"="+value+expires+"; path=/";
96: };
